UPDATE Db_Tank.dbo.Quest SET Detail = N'Vượt qua phó bản Đại hội thể thao Gà độ khó Khó và phó bản Gà Con độ khó Khó để hoàn thành nhiệm vụ.' WHERE CAST(Detail AS nvarchar(4000)) = N'通关困难难度啵咕运动会副本和困难难度小鸡副本，就可以完成任务。'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Thu thập 5 “Hạt giống” trong đấu trường và tự tay đánh bại BOSS Soran trong phó bản Bộ lạc Tà thần độ khó Khó để hoàn thành nhiệm vụ.' WHERE CAST(Detail AS nvarchar(4000)) = N'在竞技场中收集5颗“籽粒”并亲手击败困难难度邪神部落副本中的BOSS索兰恩，就可以完成任务。'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Mỗi khi nhân vật tiêu phí hợp lệ đạt 4000 Xu, sẽ được tặng Châu báu thuộc tính ×1 (khóa), phần thưởng có thể nhận cộng dồn. (Tiêu phí hợp lệ: số tiền người chơi mua đạo cụ trong Shop.)' WHERE CAST(Detail AS nvarchar(4000)) = N'角色有效消费每达到4000点券的玩家，将赠送属性宝珠×1（绑定），奖励可叠加领取。（有效消费定义：玩家在游戏商城中购买道具的金额。）'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Mỗi khi nhân vật tiêu phí hợp lệ đạt 5000 Xu, sẽ được tặng Mảnh Súng Trúc Viễn Cổ sơ cấp ×1 (khóa), phần thưởng có thể nhận cộng dồn. (Tiêu phí hợp lệ: số tiền người chơi mua đạo cụ trong Shop.)' WHERE CAST(Detail AS nvarchar(4000)) = N'角色有效消费每达到5000点券的玩家，将赠送远古竹枪初级碎片×1（绑定），奖励可叠加领取。（有效消费定义：玩家在游戏商城中购买道具的金额。）'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Hạ gục 6 người trong đấu trường để hoàn thành nhiệm vụ.' WHERE CAST(Detail AS nvarchar(4000)) = N'在竞技场中击倒6人就可以完成任务。'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Thắng 6 trận Chiến Guild để hoàn thành nhiệm vụ.' WHERE CAST(Detail AS nvarchar(4000)) = N'获胜6场公会战就可以完成任务。'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Thắng 6 trận Chiến Guild để nhận 1 Đá Tình Bạn Xanh Lam.' WHERE CAST(Detail AS nvarchar(4000)) = N'获胜6场公会战可以获得1颗蓝色友情石。'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Tự tay hạ gục BOSS Gà Mẹ trong “Phó bản Gà Con Chạy Mau” độ khó Khó để nhận 1 Đá Sinh Mệnh Xanh Lục.' WHERE CAST(Detail AS nvarchar(4000)) = N'亲手击倒困难难度“小鸡快跑副本”中的母鸡BOSS， 就可以获得1颗绿色生命石。'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Tự tay hạ gục BOSS “Trọng tài nổi giận” trong “Đại hội thể thao Gà” độ khó Thường để nhận 1 Đá Dũng Khí Tím.' WHERE CAST(Detail AS nvarchar(4000)) = N'亲手击倒普通难度“啵咕运动会”中的BOSS“愤怒的裁判”可以获得1颗紫色勇气石。'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Sau khi thu thập đủ 4 viên đá quý, bạn có thể mở “Rương Kỳ Ảo” đã ngủ say nhiều năm.' WHERE CAST(Detail AS nvarchar(4000)) = N'收集了4颗宝石后，就可以启动沉睡多年的“奇幻百宝箱”。'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Tham gia “Phó bản Gà Con” hạ gục “Gà Con Vỏ Trứng” có tỉ lệ nhận “Mặt nạ Buồn”; tự tay hạ gục “BOSS Gà Mẹ” để nhận “Mặt nạ Vui”.' WHERE CAST(Detail AS nvarchar(4000)) = N'参与“小鸡副本”击杀“蛋壳小鸡”有几率获得“悲伤面具”；亲手击倒“母鸡BOSS”可以获得“喜悦面具”。'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Vượt qua 3 phó bản Đại hội thể thao Gà (Khó), Bộ lạc Tà thần (Khó) và Đại chiến rồng (Thường) để hoàn thành nhiệm vụ.' WHERE CAST(Detail AS nvarchar(4000)) = N'通关困难啵谷运动会、困难邪神和普通龙巢这三个副本就可以完成任务。'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Ngoài thám hiểm, thi đấu với người chơi khác cũng là một phần của trò chơi. Thỉnh thoảng hãy rèn luyện kỹ năng chiến đấu, hoàn thành 4 trận đấu tự do rồi quay lại nhé~' WHERE CAST(Detail AS nvarchar(4000)) = N'除了探险外，与其他玩家竞技也是游戏的一部分，偶尔也要磨练一下自己的战斗技巧，去完成4场竞技战再回来吧～'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Bạn bè có qua có lại, hãy dùng <crThưcr> gửi cho bạn bè một <crmón quà nhỏcr>, mở ra cánh cửa tình bạn~' WHERE CAST(Detail AS nvarchar(4000)) = N'朋友之间礼尚往来，用<cr邮件cr>送给你朋友一份<cr薄礼cr>吧，开启友谊之门~'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Nhiều bạn thì dễ đi đường~ Trong <crmenu Xã giaocr> ở góc dưới bên phải và <crbảng xem trạng thái người chơicr> đều có nút kết bạn. Ngoài ra, <crTrung tâm kết bạncr> là nơi tuyệt vời để làm quen bạn mới!' WHERE CAST(Detail AS nvarchar(4000)) = N'朋友多了路好走~右下方的<cr社交菜单cr>与<cr查看玩家状态的面板cr>内都有添加好友的按钮。另外,<cr交友中心cr>是一个不错的认识朋友的好地方！'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Nghe nói Quốc vương dự định trồng rất nhiều cây Sơn thù du tại các chiến trường. Dũng sĩ nào nhặt được nhiều nhất sẽ được trọng thưởng. Cuộc thi sắp bắt đầu, mau nhanh chân lên! Cuộc tranh đoạt Sơn thù du sắp mở màn. Hoàn thành trận đấu tự do có tỉ lệ nhận Sơn thù du!' WHERE CAST(Detail AS nvarchar(4000)) = N'Nghe nói Quốc vương dự định trồng rất nhềiu cây Sơn thù du tại các chiến trường. Dũng sĩ nào nhặt được nhiều nhất sẽ được trọng thưởng. Cuộc thi sắp bắt đầu, mau nhanh chân lên!为收集茱萸的争夺战将揭开序幕。完成竞技战就有机率获得茱萸！'; SET @n += @@ROWCOUNT;
UPDATE Db_Tank.dbo.Quest SET Detail = N'Khó khăn lắm mới đánh lùi được bóng Matthias, nhưng không biết thế lực ghê gớm này từ đâu mà có, biết đâu lại còn kẻ địch khủng khiếp hơn chưa xuất hiện……' WHERE CAST(Detail AS nvarchar(4000)) = N'Khó khăn lắm mới đánh lùi được bóng Matthias,nhưng không biết thế lực ghê gớm này từ đâu mà có, biết đâu lại còn kẻ địch khủng khiếp hơn chưa xuất hiện. 人……'; SET @n += @@ROWCOUNT;
